// ── Klasyfikacja tkaniny wg składu: Naturalne / Semi-Natural ────────────
// Parsuje pola typu "58% CO, 42% PES", "100% LI", ale też polskie opisy
// wpisywane ręcznie przy własnych tkaninach: "60% Bawełna, 40% Poliester"
// albo "Len 100%". Rozpoznaje zarówno kody skrótowe z cenników dostawców
// (CO=bawełna, LI=len, WO=wełna, SI=jedwab, JU=juta, HE=konopie), jak i
// pełne nazwy PL/EN wraz z odmianami przymiotnikowymi.
// Zasada zgłoszona przez Damiana: 100% włókna naturalnego → "Naturalne";
// mieszanka włókna naturalnego z syntetykiem (PES, PA, RPET, PAN, VI, OT...)
// → "Semi-Natural"; brak włókna naturalnego w składzie (albo skład nie do
// sparsowania, np. "z obciążnikiem") → brak kategorii (null).
function _normPl(s){
  return String(s).toLowerCase()
    .replace(/ł/g,"l").replace(/ą/g,"a").replace(/ć/g,"c").replace(/ę/g,"e")
    .replace(/ń/g,"n").replace(/ó/g,"o").replace(/ś/g,"s").replace(/ź/g,"z").replace(/ż/g,"z");
}
var NATURAL_FIBER_TOKENS = [
  // kody skrótowe (jak w cennikach dostawców)
  "co","li","wo","si","ju","he",
  // polskie nazwy i odmiany przymiotnikowe/deklinacje
  "bawelna","bawelniany","bawelniana","bawelniane","bawelny","bawelnie",
  "len","lniany","lniana","lniane","lnu","lnie",
  "welna","welniany","welniana","welniane","welny","welnie",
  "jedwab","jedwabny","jedwabna","jedwabne","jedwabiu",
  "juta","jutowy","jutowa","jutowe","juty",
  "konopie","konopny","konopna","konopne","konopi",
  // angielskie nazwy (spotykane w cennikach zagranicznych)
  "cotton","linen","wool","silk","jute","hemp"
];
export function classifyFabricComposition(sklad){
  if(!sklad) return null;
  // Dopasowuje oba szyki zapisu: "60% Bawełna" oraz "Bawełna 60%"
  var re = /(\d+(?:[.,]\d+)?)\s*%\s*([\p{L}]+)|([\p{L}]+)\s*(\d+(?:[.,]\d+)?)\s*%/gu;
  var m, hasNatural=false, hasOther=false, naturalPct=0, totalPct=0;
  while((m = re.exec(String(sklad))) !== null){
    var pctStr = m[1]!=null ? m[1] : m[4];
    var word   = m[2]!=null ? m[2] : m[3];
    if(pctStr==null || !word) continue;
    var pct = parseFloat(pctStr.replace(",", "."));
    var token = _normPl(word);
    totalPct += pct;
    if(NATURAL_FIBER_TOKENS.indexOf(token) >= 0){ hasNatural = true; naturalPct += pct; }
    else hasOther = true;
  }
  if(!hasNatural || !totalPct) return null;
  if(!hasOther && naturalPct >= totalPct - 1) return "Naturalne";
  return "Semi-Natural";
}

// ── Zaciemnienie tkaniny: Blackout / Dimout ───────────────────────
// Stopień zaciemnienia nie wynika ze składu i nie ma dla niego osobnej kolumny
// w bazie — u wszystkich dostawców jest zapisany w nazwie tkaniny: "Roma FR
// Black-Out", "Skyfall Dim Out", "DIMOUT BO UNI", "Jowisz Blackout FR".
// Rozpoznajemy więc wszystkie warianty pisowni (razem / z myślnikiem / ze spacją).
// Dimout ma pierwszeństwo: kilka pozycji ma w nazwie i "Dimout", i skrót "BO",
// a to wciąż tkanina przyciemniająca, nie zaciemniająca całkowicie.
export function classifyFabricBlackout(name){
  if(!name) return null;
  var n = String(name).toLowerCase();
  if(/dim\s*-?\s*out/.test(n)) return "Dimout";
  if(/black\s*-?\s*out/.test(n)) return "Blackout";
  return null;
}

// ── Tkaniny wysokie ──────────────────────────────────────
// Szerokość beli (pole "width" w FABRICS / "height_cm" w katalogu) od której
// można uszyć zasłonę na pełną wysokość bez łączenia pasów — czyli tkaniny
// szyte "w poprzek". Wartość w jednym miejscu, żeby próg dawało się zmienić
// bez szukania po komponentach.
export var HIGH_FABRIC_MIN_CM = 320;
export var HIGH_FABRIC_TAG = "Wysokie (320+ cm)";
export function isHighFabric(widthCm){
  return widthCm != null && +widthCm >= HIGH_FABRIC_MIN_CM;
}

// ── Nadpisania tkanin z Katalogu (Magazyn → Katalog) ───────────────────
// Cache w pamiećci procesu, wypełniany raz przy starcie apki (App.jsx wywołuje
// primeFabricOverrides po pobraniu catalog_items z Supabase). Klucz nadpisania
// to base_key w formacie "tkaniny::<nazwa>" (patrz ScreenWarehouse.jsx).
// Dawne nazwy tkanin -> aktualne (zmiany nazw w FABRICS). Stare wyceny i nadpisania
// z Katalogu trzymaja nazwe jako klucz, wiec mapujemy je na nowa nazwe.
var FABRIC_LEGACY_NAMES = {
  "Aurora Capture":"Aurora / Capture",
  "Euphoria":"Euphoria / Capture",
  "Explore":"Explore / Capture",
  "Fame":"Fame / Capture",
  "Glaze":"Glaze / Capture",
  "Halo":"Halo / Capture",
  "Lucente Capture":"Lucente / Capture",
  "Lumi\u00e8re":"Lumi\u00e8re / Capture",
  "Moire":"Moire / Capture",
  "Rumour":"Rumour / Capture",
  "Sign":"Sign / Capture",
  "Thread":"Thread / Capture",
  "Tomorrow":"Tomorrow / Capture",
  "Ultimate":"Ultimate / Capture"
};
var _fabricOverrides = {};
// Tkaniny wlasne (dodane recznie w Magazyn -> Katalog, bez base_key, grupa "tkaniny")
var _customFabrics = [];
function _rowToFabric(r){
  return {
    name: r.name,
    brutto: r.price!=null ? r.price : null,
    prod: r.meta || "W\u0142asne",
    width: r.height_cm!=null ? r.height_cm : null,
    zakup: r.purchase_price!=null ? r.purchase_price : null,
    sklad: r.composition || null,
    belkowa: r.belka_price!=null ? r.belka_price : null,
    gramatura: r.weight_gsm!=null ? r.weight_gsm : null,
    kurczliwosc: r.shrinkage_pct!=null ? r.shrinkage_pct : null,
    flameRetardant: !!r.flame_retardant,
    soundproof: !!r.soundproof,
    custom: true
  };
}
export function primeFabricOverrides(rows){
  _fabricOverrides = {};
  _customFabrics = [];
  (rows||[]).forEach(function(r){
    if(r.base_key && r.base_key.indexOf("tkaniny::")===0){
      var k = r.base_key.slice(9);
      if(FABRIC_LEGACY_NAMES[k]){
        k = FABRIC_LEGACY_NAMES[k];
        if(_fabricOverrides[k]) return; // nowszy wpis pod nowa nazwa ma pierwszenstwo
        if(r.meta==="Capture") r = Object.assign({}, r, {meta:"Vadain"});
      }
      _fabricOverrides[k] = r;
    } else if(!r.base_key && r.group_id==="tkaniny" && r.name){
      _customFabrics.push(_rowToFabric(r));
    }
  });
}
// Pelna lista tkanin dostepna w wycenach: cennik bazowy (z nadpisaniami z Katalogu,
// bez pozycji ukrytych) + tkaniny wlasne dodane recznie w Katalogu.
export function getAllFabrics(){
  var out = [];
  FABRICS.forEach(function(f){
    var ov = _fabricOverrides[f.name];
    if(ov && ov.hidden) return;
    var eff = getFabricEffective(f.name);
    out.push(eff ? Object.assign({}, f, eff) : f);
  });
  var seen = {};
  out.forEach(function(f){ seen[f.name]=1; });
  _customFabrics.forEach(function(f){ if(!seen[f.name]){ seen[f.name]=1; out.push(f); } });
  return out;
}
// Zwraca efektywną tkaninę (baza FABRICS + nadpisanie z katalogu, jeśli istnieje)
export function getFabricEffective(name){
  if(name && FABRIC_LEGACY_NAMES[name]) name = FABRIC_LEGACY_NAMES[name];
  var base = FABRICS.find(function(f){return f.name===name;});
  var ov = _fabricOverrides[name];
  if(!base && !ov){
    var cf = _customFabrics.find(function(f){return f.name===name;});
    return cf ? Object.assign({}, cf) : null;
  }
  return {
    name: name,
    brutto: (ov && ov.price!=null) ? ov.price : (base?base.brutto:null),
    width:  (ov && ov.height_cm!=null) ? ov.height_cm : (base?base.width:null),
    prod:   (ov && ov.meta) ? ov.meta : (base?base.prod:"-"),
    zakup:  (ov && ov.purchase_price!=null) ? ov.purchase_price : (base?base.zakup:null),
    sklad:  (ov && ov.composition) ? ov.composition : (base?base.sklad:null),
    belkowa:(ov && ov.belka_price!=null) ? ov.belka_price : (base?base.belkowa:null),
    gramatura:(ov && ov.weight_gsm!=null) ? ov.weight_gsm : (base?base.gramatura:null),
    kurczliwosc:(ov && ov.shrinkage_pct!=null) ? ov.shrinkage_pct : (base && base.kurczliwosc!=null ? base.kurczliwosc : null),
    flameRetardant: (ov && ov.flame_retardant!=null) ? !!ov.flame_retardant : !!(base && base.flameRetardant),
    soundproof: (ov && ov.soundproof!=null) ? !!ov.soundproof : !!(base && base.soundproof)
  };
}
// Bestsellery tkanin — pokazywane jako pierwsza sekcja po otwarciu listy tkanin w wycenach
// (FabPicker w ProdCard.jsx), pogrupowane wg kategorii; osobne zestawy dla zasłon i firan.
export const FABRIC_BESTSELLERS = {
  zaslona: [
    {cat:"A'la naturalne, strukturalne", names:["34280","Wave","Corsica","Riki"]},
    {cat:"Welury", names:["Velvet","Spring"]},
    {cat:"100% Naturalne", names:["Nam"]},
    {cat:"Gładkie", names:["34200","Wonder"]}
  ],
  firana: [
    {cat:"Strukturalne, naturalne", names:["Yita"]},
    {cat:"Gładkie", names:["David"]},
    {cat:"100% Natural", names:["Pallino"]}
  ]
};
// Zwraca bestsellery dla danego typu produktu ("zaslona" | "firana") jako [{cat, fabrics:[...]}],
// z pominięciem pozycji ukrytych w Katalogu; dane zawsze aktualne (getFabricEffective = baza + nadpisania).
export function getBestsellerFabrics(prodType){
  var groups = FABRIC_BESTSELLERS[prodType];
  if(!groups) return [];
  return groups.map(function(g){
    var fabrics = g.names.map(function(n){
      var ov = _fabricOverrides[n];
      if(ov && ov.hidden) return null;
      return getFabricEffective(n);
    }).filter(Boolean);
    return {cat:g.cat, fabrics:fabrics};
  }).filter(function(g){return g.fabrics.length>0;});
}

